package com.autoops.ai.provider;import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.stereotype.Service;import org.springframework.web.client.RestClient;import java.util.*;@Service public class OpenRouterAIProvider implements AIProvider{private final RestClient client;private final String model;public OpenRouterAIProvider(@Value("${autoops.ai.base-url}")String url,@Value("${autoops.ai.api-key}")String key,@Value("${autoops.ai.model}")String model){client=RestClient.builder().baseUrl(url).defaultHeader(HttpHeaders.AUTHORIZATION,"Bearer "+key).build();this.model=model;}@SuppressWarnings("unchecked")public AIResponse chat(List<Message> messages,List<Map<String,Object>> tools){Map<String,Object> body=new LinkedHashMap<>();body.put("model",model);body.put("messages",messages.stream().map(m->Map.of("role",m.role(),"content",m.content())).toList());Map<String,Object> r=client.post().uri("/chat/completions").contentType(MediaType.APPLICATION_JSON).body(body).retrieve().body(Map.class);if(r==null)return new AIResponse("",List.of());List<Map<String,Object>> choices=(List<Map<String,Object>>)r.get("choices");if(choices==null||choices.isEmpty())return new AIResponse("",List.of());Map<String,Object> msg=(Map<String,Object>)choices.get(0).get("message");Object content=msg.get("content");return new AIResponse(content==null?"":content.toString(),List.of());}}
